import{_ as r,C as o,o as a,c as l,a4 as t,b as i,w as s,a as p,E as c,a5 as d}from"./chunks/framework.BRzJ4ijD.js";const _=JSON.parse('{"title":"Raft 详解","description":"","frontmatter":{},"headers":[],"relativePath":"distributed/consensus/raft.md","filePath":"distributed/consensus/raft.md","lastUpdated":1788475713000}'),m={name:"distributed/consensus/raft.md"};function h(g,e,u,b,f,y){const n=o("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="raft-详解" tabindex="-1">Raft 详解 <a class="header-anchor" href="#raft-详解" aria-label="Permalink to &quot;Raft 详解&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p><strong>Raft</strong> (Ongaro &amp; Ousterhout 2014, USENIX ATC) 是 Diego Ongaro 在 Stanford 写博士时设计的&quot;易理解共识算法&quot; —— 目标是&quot;为工业维护团队而写而不是为研究算法的人&quot;。Raft 把共识问题分成三个子问题: <strong>Leader Election</strong>, <strong>Log Replication</strong>, <strong>Safety</strong>, 每个独立设计 + 强约束, 比 Multi-Paxos 直观。 etcd、Consul、TiKV、CockroachDB、RethinkDB、Kafka controller metadata (KRaft mode)、Notion、Apple FoundationDB**、Apache Ratis 都用 Raft。本章梳理算法细节 (term、选举、AppendEntries、log matching、commit index、membership change), 工程实现 (默认配置、性能数字、网络分区行为), typical gotchas (pre-vote、joint consensus、read index、leader lease)。</p><hr><h2 id="一、核心概念" tabindex="-1">一、核心概念 <a class="header-anchor" href="#一、核心概念" aria-label="Permalink to &quot;一、核心概念&quot;">​</a></h2><h3 id="_1-服务器状态机" tabindex="-1">1. 服务器状态机 <a class="header-anchor" href="#_1-服务器状态机" aria-label="Permalink to &quot;1. 服务器状态机&quot;">​</a></h3><p>每节点三种状态:</p><ul><li><strong>Follower</strong>:被动接收 leader 的 AppendEntries + RequestVote。</li><li><strong>Candidate</strong>:选举期间, 自我 promote、RequestVote 拉票, 等待 majority (N/2+1)。</li><li><strong>Leader</strong>:唯一接收 client 请求, 主动复制 log 到 followers。</li></ul>',8)),(a(),i(d,null,{default:s(()=>[c(n,{id:"mermaid-36",class:"mermaid",graph:"stateDiagram-v2%0A%20%20%20%20%5B*%5D%20--%3E%20Follower%3A%20%E5%90%AF%E5%8A%A8%0A%20%20%20%20Follower%20--%3E%20Candidate%3A%20election%20timeout%0A%20%20%20%20Candidate%20--%3E%20Leader%3A%20%E6%8B%BF%E5%88%B0%20majority%20vote%0A%20%20%20%20Candidate%20--%3E%20Follower%3A%20%E6%94%B6%E5%88%B0%E5%90%88%E6%B3%95%20leader%20AppendEntries%20or%20higher%20term%0A%20%20%20%20Candidate%20--%3E%20Candidate%3A%20election%20timeout%20%E9%87%8D%E5%8F%91%20RequestVote%0A%20%20%20%20Leader%20--%3E%20Follower%3A%20%E5%8F%91%E7%8E%B0%E6%9B%B4%E9%AB%98%20term%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t(`<h3 id="_2-term" tabindex="-1">2. Term <a class="header-anchor" href="#_2-term" aria-label="Permalink to &quot;2. Term&quot;">​</a></h3><p>term 是 monotonic increase integer, <strong>任期编号</strong>。每次选举 term+1, 每次 RPC request/response 携带 term; 收到 term 比自己低的 RPC 拒绝, 收 to higher term 立即 downgrade 自己.</p><p>term 是 Raft 的逻辑时钟, 替代 Paxos proposal_number。</p><h3 id="_3-rpc" tabindex="-1">3. RPC <a class="header-anchor" href="#_3-rpc" aria-label="Permalink to &quot;3. RPC&quot;">​</a></h3><p>两种 RPC:</p><ul><li><strong>RequestVote(term, candidate_id, last_log_index, last_log_term)</strong>: candidate 拉票。</li><li><strong>AppendEntries(term, leader_id, prev_log_index, prev_log_term, entries[], leader_commit)</strong>: leader 复制 log + heartbeat (空 entries 充当 heartbeat)。</li></ul><hr><h2 id="二、leader-election" tabindex="-1">二、Leader Election <a class="header-anchor" href="#二、leader-election" aria-label="Permalink to &quot;二、Leader Election&quot;">​</a></h2><h3 id="election-timeout" tabindex="-1">Election Timeout <a class="header-anchor" href="#election-timeout" aria-label="Permalink to &quot;Election Timeout&quot;">​</a></h3><p>随机化 <code>T_election ∈ [T_min, T_max]</code> 默认 150-300ms。 当 follower 在此期间未收 leader heartbeat, → 转 candidate:</p><ol><li>term++, vote self, send <strong>RequestVote</strong> to all peers.</li><li>等三种结局: <ul><li>收 majority &quot;yes&quot; → leader, 立即 send heartbeat 确认权威.</li><li>收合法 leader (AppendEntries with current term) → follower.</li><li>超时无 majority → 加 tirη.term++;重选.</li></ul></li></ol><h3 id="投票约束" tabindex="-1">投票约束 <a class="header-anchor" href="#投票约束" aria-label="Permalink to &quot;投票约束&quot;">​</a></h3><p>投票方仅投给满足以下条件 candidate:</p><ol><li>自己当前 term 与 candidate term 相等(=)或 lower (then bump term)</li><li>自己未投过 (投票 history 包括 restart 后 persisted term)</li><li>candidate 的 log <strong>at least as up-to-date</strong>: 比较候选 last_log_index 与自己 last_log_index, 若 last_log_term 更高 → newer. 同 term 时 compare index。</li></ol><p><strong>Up-to-date 比较规则保证被选 leader 含 all committed entries</strong>——这是 Raft 的 safety invariant (Leader Completeness)。</p><h3 id="防止-split-vote" tabindex="-1">防止 split vote <a class="header-anchor" href="#防止-split-vote" aria-label="Permalink to &quot;防止 split vote&quot;">​</a></h3><p>randomized election timeout 让多 followers 不太可能同时转 candidate. 实际工程 (etcd) <code>ElectionTimeout=100-150ms</code>, 集群越小冲突小。</p><h3 id="pre-vote-pingao-et-al-etcd-extension" tabindex="-1">Pre-Vote (Pingao et al. etcd extension) <a class="header-anchor" href="#pre-vote-pingao-et-al-etcd-extension" aria-label="Permalink to &quot;Pre-Vote (Pingao et al. etcd extension)&quot;">​</a></h3><p>防止短暂网络分区导致 节点 elevated term 后 &quot;传染&quot; 回原集群触发不必要选举:</p><ol><li>candidate 在 RequestVote 之前发 <strong>PreVote</strong> 询问 &quot;如果我请求, 我能拿到 majority 吗&quot;。</li><li>follower 仅在 <strong>leader heartbeat 长时间无收</strong>时回 yes。</li><li>candidate 拿到 majority PreVote ack 才真 term++ 发 RequestVote.</li></ol><p>etcd 3.x preferred, METCommission academic thesis. Pre-Vote 是 Raft 论文未包含的工程 extension, 现 de-facto standard.</p><hr><h2 id="三、log-replication" tabindex="-1">三、Log Replication <a class="header-anchor" href="#三、log-replication" aria-label="Permalink to &quot;三、Log Replication&quot;">​</a></h2><h3 id="appendentries-rpc" tabindex="-1">AppendEntries RPC <a class="header-anchor" href="#appendentries-rpc" aria-label="Permalink to &quot;AppendEntries RPC&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>leader.send AppendEntries {</span></span>
<span class="line"><span>  term, leader_id,</span></span>
<span class="line"><span>  prev_log_index, prev_log_term,    // 最近一条已复制 entry</span></span>
<span class="line"><span>  entries[],                        // 新 entries (heartbeat 时空)</span></span>
<span class="line"><span>  leader_commit                     // 当前 commit_index</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>follower:</span></span>
<span class="line"><span>  1. if term &lt; current -&gt; reject</span></span>
<span class="line"><span>  2. if log[prev_log_index].term != prev_log_term -&gt; reject (log inconsistency)</span></span>
<span class="line"><span>  3. for each entry in entries:</span></span>
<span class="line"><span>       if local entry conflicts (same index, different term) -&gt; 清掉冲突的与所有后续</span></span>
<span class="line"><span>       append entry</span></span>
<span class="line"><span>  4. if leader_commit &gt; commit_index: commit_index = min(leader_commit, last_new_index)</span></span>
<span class="line"><span>  5. reply (term, success, last_index, match_index)</span></span></code></pre></div><h3 id="log-matching-property" tabindex="-1">Log Matching Property <a class="header-anchor" href="#log-matching-property" aria-label="Permalink to &quot;Log Matching Property&quot;">​</a></h3><ul><li>若两 log entries 同 index 同 term, 它们 value 必相同 (仙做 safety).</li><li>若两 log entries 同 index 同 term, 它们之前所有 entries 必相同.</li></ul><p>prev_log_index/prev_log_term 强制 backward check, follower 不匹配时 reject, leader decrement nextIndex 重试. 最终一致是 eventual + 失败时回退—update 沿图。</p><h3 id="commit-rule" tabindex="-1">Commit Rule <a class="header-anchor" href="#commit-rule" aria-label="Permalink to &quot;Commit Rule&quot;">​</a></h3><p>leader commit entry 必须满足:</p><ol><li>该 entry 在 majority nodes 上 stored (already replicated).</li><li>该 entry 是 current term 写的。</li></ol><p><strong>条件 2 是关键</strong>——Raft 论文 Section 5.4.2 Fig 8 的反例: 假若 leader 旧 term 时复制的 entry (但未 commit) 后来由新 leader commit 是 unsafe (因为可能 stale 副本)。 Raft 不直接 commit 旧 term entry;新 leader 必须用自己 term 写一条 entry, commit 自己 term entry 时<strong>间接 commit</strong> 所有 prior entries (因 log matching 保证)。</p><h3 id="state-safety-leader-completeness" tabindex="-1">State Safety (Leader Completeness) <a class="header-anchor" href="#state-safety-leader-completeness" aria-label="Permalink to &quot;State Safety (Leader Completeness)&quot;">​</a></h3><p><strong>已被选出 leader 必含所有 committed entries</strong>——选举时 up-to-date check (last_log_index/last_term) 保证投票只投给同 up-to-date candidate, candidate 的 log 必延展 committed entries (因 majority overlap).</p><h3 id="snapshot-与-log-compaction" tabindex="-1">Snapshot 与 Log Compaction <a class="header-anchor" href="#snapshot-与-log-compaction" aria-label="Permalink to &quot;Snapshot 与 Log Compaction&quot;">​</a></h3><p>log 增长会爆磁盘 + 重启慢, 周期性<strong>快照</strong> :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. leader 在 commit index 处 snapshot (state machine 应用前)→ discard log &lt; snapshot_last_index</span></span>
<span class="line"><span>2. InstallSnapshot RPC 给 lag-behind followers</span></span>
<span class="line"><span>3. follower 收到 snapshot → 写本地 apply → discard 自己 log &lt; snapshot_last_index</span></span></code></pre></div><p>etcd 每 10000 entries 触发; TiKV 每 64MB region size。</p><hr><h2 id="四、membership-change" tabindex="-1">四、Membership Change <a class="header-anchor" href="#四、membership-change" aria-label="Permalink to &quot;四、Membership Change&quot;">​</a></h2><h3 id="joint-consensus-论文-section-6" tabindex="-1">Joint Consensus (论文 Section 6) <a class="header-anchor" href="#joint-consensus-论文-section-6" aria-label="Permalink to &quot;Joint Consensus (论文 Section 6)&quot;">​</a></h3><p>Raft 论文给出 general solution = <strong>Joint Consensus</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>集群配置 C_old → C_new, 中间过渡期 C_old,new 同时活跃:</span></span>
<span class="line"><span>1. leader propose &quot;C_old,new&quot; entry to log, accepted by majority(C_old) ∩ majority(C_new)</span></span>
<span class="line"><span>2. entry committed → 节点同时按两 config 各自看待</span></span>
<span class="line"><span>3. propose &quot;C_new&quot; entry → commit (只要 C_new majority) → 切到 C_new</span></span>
<span class="line"><span>4. 不在 C_new 的节点退出</span></span></code></pre></div><p>joint consensus 保证两 majority <strong>总 overlap</strong>, 防 split-brain。 但两 quorum 独立 同时 active 要 majority(C_old) ∩ majority(C_new) ack, 复杂度大。</p><h3 id="single-server-change-etcd-consul-实际常用" tabindex="-1">Single-Server Change (etcd/Consul 实际常用) <a class="header-anchor" href="#single-server-change-etcd-consul-实际常用" aria-label="Permalink to &quot;Single-Server Change (etcd/Consul 实际常用)&quot;">​</a></h3><p>每次只 add/remove <strong>一个</strong> server。 关键 invariant: <code>|C_old| = |C_new| ± 1</code>, 通过简单的算术: 对奇偶 N 节点, 两 majority 必 overlap 至少 1 node。 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mo fence="true">⌈</mo><mo stretchy="false">(</mo><mi>N</mi><mo>+</mo><mn>1</mn><mo stretchy="false">)</mo><mi mathvariant="normal">/</mi><mn>2</mn><mo fence="true">⌉</mo></mrow><mo>+</mo><mrow><mo fence="true">⌈</mo><mo stretchy="false">(</mo><mi>N</mi><mo>+</mo><mn>2</mn><mo stretchy="false">)</mo><mi mathvariant="normal">/</mi><mn>2</mn><mo fence="true">⌉</mo></mrow><mo>=</mo><mi>N</mi><mo>+</mo><mn>1</mn><mo>&gt;</mo><mi>N</mi></mrow><annotation encoding="application/x-tex">\\left\\lceil(N+1)/2\\right\\rceil + \\left\\lceil(N+2)/2\\right\\rceil = N + 1 &gt; N</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;">⌈</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord">1</span><span class="mclose">)</span><span class="mord">/2</span><span class="mclose delimcenter" style="top:0em;">⌉</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;">⌈</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord">2</span><span class="mclose">)</span><span class="mord">/2</span><span class="mclose delimcenter" style="top:0em;">⌉</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6835em;vertical-align:-0.0391em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> ⇒ overlap ≥ 1.</p><p>single-server 可简化实现: 直接 propose 一个 special config entry, ACcept 后 stale config 节点退出。 工程上):</p><ul><li><strong>Add</strong>: leader propose AddNode, follower 收到后开始接受 AppendEntries 与 RequestVote。</li><li><strong>Remove</strong>: leader propose RemoveNode, target follower 检测到自己不在新 config → stop。</li><li>一次只一个 change, 然后等下一 change。</li></ul><p>etcd <code>MemberAdd</code> API 即此; Raft 论文也允许 batch 变更(multi-server removal) 走 joint consensus, 但 etcd/Consul 都选择 single-server + 多次循环。</p><hr><h2 id="五、read-处理" tabindex="-1">五、Read 处理 <a class="header-anchor" href="#五、read-处理" aria-label="Permalink to &quot;五、Read 处理&quot;">​</a></h2><h3 id="linearizable-read" tabindex="-1">Linearizable Read <a class="header-anchor" href="#linearizable-read" aria-label="Permalink to &quot;Linearizable Read&quot;">​</a></h3><p>Direct read on leader 不稳: follower 没 at-newest-leader 起门 leader 隔离时间 client reads old mutation → read 不是 linearizable. 解决方案:</p><h4 id="_1-read-index" tabindex="-1">1. Read Index <a class="header-anchor" href="#_1-read-index" aria-label="Permalink to &quot;1. Read Index&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. leader 记录当前 commit_index</span></span>
<span class="line"><span>2. 发 heartbeat to majority 确认自己仍是 leader (1 RTT)</span></span>
<span class="line"><span>3. 等待 local state machine apply 到 commit_index</span></span>
<span class="line"><span>4. 执行 read, 返回 client</span></span></code></pre></div><h4 id="_2-lease-read" tabindex="-1">2. Lease Read <a class="header-anchor" href="#_2-lease-read" aria-label="Permalink to &quot;2. Lease Read&quot;">​</a></h4><p>leader 用 lease (heartbeat-driven, leader elected 后 clock tick 自, 平均 sender 节点 确认为 leader, lease 内 read 不 quorum check.lease 过期必须 renew, 否则 relinquish leadership.</p><p><strong>风险</strong>: lease 期间 leader 长 GC pause → lease timeout 后仍误以为自己是 leader, 同时新 leader 也在另一分区上选出来 —— stale leader 服务读违反 linearizability。</p><p>etcd 3.x 的 <strong>CheckQuorum=true</strong> 让 leader 每次 heartbeat 主动确认 majority 仍可 reach, 若 quorum 失联立即 step down; 这是 lease 读 + lease 校验的核心修案。</p><hr><h2 id="六、工业配置与性能" tabindex="-1">六、工业配置与性能 <a class="header-anchor" href="#六、工业配置与性能" aria-label="Permalink to &quot;六、工业配置与性能&quot;">​</a></h2><h3 id="etcd-默认值" tabindex="-1">etcd 默认值 <a class="header-anchor" href="#etcd-默认值" aria-label="Permalink to &quot;etcd 默认值&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>heartbeat-interval=100ms                # leader-to-follower heartbeat</span></span>
<span class="line"><span>election-timeout=1000ms                 # 必须 &gt;&gt; heartbeat (10x)</span></span>
<span class="line"><span>snapshot-count=10000</span></span>
<span class="line"><span>quota-backend-bytes=2GB</span></span></code></pre></div><p>实际 etcd 调用 <code>election-timeout</code> 既给 candidate 等 majority 投票超时, 也给 follower 等 leader 心跳超时。推荐 <code>election-timeout</code> 是 <code>heartbeat</code> 的 10 倍以吸收 GC pause 与网络抖动。</p><h3 id="跨数据中心典型调参" tabindex="-1">跨数据中心典型调参 <a class="header-anchor" href="#跨数据中心典型调参" aria-label="Permalink to &quot;跨数据中心典型调参&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>heartbeat=200ms (跨 dc 单 RTT ~20-100ms)</span></span>
<span class="line"><span>election-timeout=1000-3000ms (5-10× heartbeat)</span></span></code></pre></div><h3 id="性能数字-etcd-5-nodes-集群-默认设置" tabindex="-1">性能数字 (etcd 5 nodes 集群, 默认设置) <a class="header-anchor" href="#性能数字-etcd-5-nodes-集群-默认设置" aria-label="Permalink to &quot;性能数字 (etcd 5 nodes 集群, 默认设置)&quot;">​</a></h3><ul><li>Throughput: ~10-20k writes/s (range 200B per write)</li><li>Write latency: P50 ~10ms, P99 ~50ms</li></ul><h3 id="tikv-cockroachdb-的优化" tabindex="-1">TiKV / CockroachDB 的优化 <a class="header-anchor" href="#tikv-cockroachdb-的优化" aria-label="Permalink to &quot;TiKV / CockroachDB 的优化&quot;">​</a></h3><ul><li><strong>Batch</strong>: 多 entries per AppendEntries (wait_group)</li><li><strong>Pipeline</strong>: leader 提议后立即 reply client, 与 fan-out 并行</li><li><strong>Async pre-write</strong>: 提交 batch 不等 follow ack, 同时 fire 下 batch</li></ul><hr><h2 id="七、典型事故" tabindex="-1">七、典型事故 <a class="header-anchor" href="#七、典型事故" aria-label="Permalink to &quot;七、典型事故&quot;">​</a></h2><h3 id="etcd-3-0-—-跨-dc-election-timeout-过小" tabindex="-1">etcd 3.0 — 跨 DC Election Timeout 过小 <a class="header-anchor" href="#etcd-3-0-—-跨-dc-election-timeout-过小" aria-label="Permalink to &quot;etcd 3.0 — 跨 DC Election Timeout 过小&quot;">​</a></h3><p>某用户跨美东/欧 DC 部署 etcd, 默认 <code>election-timeout=1000ms</code>, 但跨洲 RTT 200-300ms 抖动, 多次观察到 leader 误判失去心跳并触发频繁选举——有时 5 分钟内 3 次 leader 切换, 上层 client 大量 retry, service 出现 5-10s 写阻塞。Fix: 调增 <code>election-timeout=3000ms</code>, 让 heartbeat 远小于 election timeout, 使跨 DC RTT 抖动不再触发不必要的 re-election.</p><h3 id="apache-ratis-—-snapshot-与-in-flight-log-race" tabindex="-1">Apache Ratis — Snapshot 与 In-Flight Log Race <a class="header-anchor" href="#apache-ratis-—-snapshot-与-in-flight-log-race" aria-label="Permalink to &quot;Apache Ratis — Snapshot 与 In-Flight Log Race&quot;">​</a></h3><p>Apache Ratis (Java Raft lib, 用于 Ozone) 早期版本: leader 给 lagging follower 发 InstallSnapshot 时, follower 同时可能收到旧 AppendEntries, 导致 log entry index 与 snapshot index 冲突, persistent 状态破坏需 manual repair. Fix: Ratis 3.x 加 snapshot receipt barrier, follower 收 InstallSnapshot 时拒收任何 AppendEntries 直到 snapshot apply 完成。</p><h3 id="kafka-kraft-—-controller-migration-snapshot-mismatch" tabindex="-1">Kafka KRaft — Controller Migration Snapshot Mismatch <a class="header-anchor" href="#kafka-kraft-—-controller-migration-snapshot-mismatch" aria-label="Permalink to &quot;Kafka KRaft — Controller Migration Snapshot Mismatch&quot;">​</a></h3><p>Kafka 3.x 引入 KRaft 替代 ZooKeeper 后, 某次 controller failover 后 new controller snapshot version 与 majority quorum 上 log 状态不一致(因 snapshot 写与 log 写不在同一 fsync), 触发 metadata topic 损坏。Fix KIP-866: log-snapshot atomic fsync group。</p><h3 id="tikv-—-网络分区期间-leader-lease-仍服务读" tabindex="-1">TiKV — 网络分区期间 leader lease 仍服务读 <a class="header-anchor" href="#tikv-—-网络分区期间-leader-lease-仍服务读" aria-label="Permalink to &quot;TiKV — 网络分区期间 leader lease 仍服务读&quot;">​</a></h3><p>长时间 leader 自认 lease 已过期但 GC pause 长, follower 已选 new leader, 两 leader 同时存在——短暂 stale read. Fix: TiKV 用 hybrid logical clock + max lease 自适应(known lease-peer, max block wait)。</p><hr><h2 id="八、易错清单" tabindex="-1">八、易错清单 <a class="header-anchor" href="#八、易错清单" aria-label="Permalink to &quot;八、易错清单&quot;">​</a></h2><ol><li><strong>Election Timeout 必须 &gt;&gt; Heartbeat Interval</strong>: 推荐 ≥ 10× heartbeat, 防 follower 误判 leader heartbeat 丢失触发 election。</li><li><strong>PreVote 必开启</strong>: 防止短期间分区后 isolated node 不断 term++, 回归后传染整个集群 term inflation 触发 unnecessary elections。</li><li><strong>旧 term 写的 entry 即使被多数复制, 也必须由 current term entry 间接 commit</strong>: 否则 Fig 8 反例, stale leader rejoin 后可能覆盖。</li><li><strong>Snapshot 必须包含 state machine snapshot index 之前所有 apply 状态</strong>: follower 收 InstallSnapshot 必须原子替换 local state, 防 partial snapshot apply 中 crash 状态混乱。</li><li><strong>Membership change 单 server 变更</strong>: 避免一次性 add/remove 多 node 时 (C_old majority) 与 (C_new majority) 不再 overlap。</li><li><strong>Client writes 必须 idempotent</strong>: command_id 去重, 否则 raft reply lost client retry 时双执行 (e.g., accounts transfer 重复执行)。</li><li><strong>Read Linearizable 一定要 Read-Index 或 Lease (而不裸读)</strong>: 裸读可能读到 stale leader 的 local state, 违反 linearizability。</li><li><strong>Follower 接 InstallSnapshot 期间必须 ignore AppendEntries</strong>: state machine 半 apply snapshot 极易损坏 log consistency invariant。</li><li><strong>Pipeline + Batch 优化得记 in-flight entries</strong>: leader reply 前不一定 commit, lost leader 切换时 in-flight entries 已写 log但未 commit, 必须 resend or discard by new leader&#39;s log overwrite. 协议正确已经被 Log Matching Property 保 safety, 但 client side 一定要 idempotent。</li></ol><hr><h2 id="九、这一章带走的东西" tabindex="-1">九、这一章带走的东西 <a class="header-anchor" href="#九、这一章带走的东西" aria-label="Permalink to &quot;九、这一章带走的东西&quot;">​</a></h2><ol><li>Raft 拆分 Leader Election / Log Replication / Safety 三个独立 subproblem, 比 Paxos 易理解。</li><li>Term 是 Raft 的逻辑时钟; 强约束 (lower term RPC reject, 看到 higher term 自己 downgrade) 保证 algorithm 不协议错乱。</li><li>Log Matching Property 强 backward check, follower 拒绝 prev_log 不匹配的 AppendEntries, leader 减 next_index 重试, 最终一致。</li><li>Commit Rule 必须 <strong>current term entry 间接 commit</strong> 旧 term entries, 防 Fig 8 反例。</li><li>Raft read path Linearizable 通过 <strong>ReadIndex (heartbeat confirmation)</strong> 或 <strong>Lease Read</strong> 实现, 每次 read 1 RTT 或 0 RTT (lease held).</li><li>Membership change 推荐 <strong>single-server change</strong> (always maj(C_old) ∩ maj(C_new) 非空), 避免 joint consensus 的双 majority 死锁。</li><li>Pre-Vote 防 partition-induced term inflation, etcd 默认开启。</li></ol><hr><p>下一节 → <a href="./linearizability">ZooKeeper / etcd / Linearizability</a></p>`,88))])}const k=r(m,[["render",h]]);export{_ as __pageData,k as default};
